APX.ma = {"country":{"name":"Morocco","tagline":"The Arab world's leading quality producer, with an AOC in the Atlas foothills and a national love of vin gris.","classification":"Morocco's system, set up from the 1970s and revised in the 1990s and 2000s, has about 14 AOG zones (appellations d'origine garanties) and one AOC, Coteaux de l'Atlas 1er Cru. 'Château' status for single estates was first granted to Château Roslane in 2009."},"regions":[{"name":"Eastern Morocco (Berkane)","slug":"eastern-morocco-berkane","tagline":"","ids":["ma-angad","ma-beni-sadden","ma-berkane"]},{"name":"El Jadida (Doukkala)","slug":"el-jadida-doukkala","tagline":"","ids":["ma-doukkala"]},{"name":"Meknès and Fès","slug":"meknes-and-fes","tagline":"","ids":["ma-beni-mtir","ma-coteaux-de-latlas-1er-cru","ma-guerrouane","ma-saiss","ma-zerhoune"]},{"name":"Northern plains (Gharb)","slug":"northern-plains-gharb","tagline":"","ids":["ma-gharb"]},{"name":"Rabat and Casablanca","slug":"rabat-and-casablanca","tagline":"","ids":["ma-chellah","ma-sahel","ma-zaer","ma-zemmour","ma-zenata"]}],"items":{"ma-angad":{"name":"Angad","cat":"AOG","region":"Eastern Morocco (Berkane)","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"The Angad plain around Oujda in the far east. One of Morocco's driest wine areas, near the Algerian border, it makes sturdy reds from Carignan, Cinsault and Grenache. It is one of the three AOGs of the Oriental region with Berkane and Beni Sadden.","rslug":"eastern-morocco-berkane"},"ma-beni-mtir":{"name":"Beni M'tir","cat":"AOG","region":"Meknès and Fès","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Plateau south of Meknès at around 700 to 800 metres, among the coolest and highest Moroccan vineyards, including the area around Boufekrane and El Hajeb. The altitude and cool nights give fresher reds and some of Morocco's best whites, and Château Roslane's AOC vineyards lie at its edge.","rslug":"meknes-and-fes"},"ma-beni-sadden":{"name":"Beni Sadden","cat":"AOG","region":"Eastern Morocco (Berkane)","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"A small eastern zone. It is one of the three eastern AOGs, with Berkane and Angad, in Morocco's dry Oriental region. Its exact boundaries and producers could not be verified for this atlas.","rslug":"eastern-morocco-berkane"},"ma-berkane":{"name":"Berkane","cat":"AOG","region":"Eastern Morocco (Berkane)","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Eastern zone near the Mediterranean and the Algerian border, around Berkane; reds and rosés. The Moulouya plain and the Beni Snassen foothills have a Mediterranean climate, warmer and drier than the Meknès plateau. Wineries here make mostly reds and rosés.","rslug":"eastern-morocco-berkane"},"ma-chellah":{"name":"Chellah","cat":"AOG","region":"Rabat and Casablanca","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Named after the Roman and Merinid site of Chellah at Rabat; vineyards on the coastal hinterland. The Rabat and Casablanca hinterland was one of the main vineyard areas of the French protectorate, close to the big urban markets.","rslug":"rabat-and-casablanca"},"ma-coteaux-de-latlas-1er-cru":{"name":"Coteaux de l'Atlas 1er Cru","cat":"AOC","region":"Meknès and Fès","created":"2001","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Morocco's only AOC, created in 2001 for vineyards of Celliers de Meknès on the Meknès plateau around Château Roslane, at about 600 to 700 metres in the foothills of the Middle Atlas; mainly red blends of Cabernet Sauvignon, Merlot and Syrah aged in oak.","rslug":"meknes-and-fes"},"ma-doukkala":{"name":"Doukkala","cat":"AOG","region":"El Jadida (Doukkala)","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Inland from El Jadida around Boulaouane, whose Castel-owned brand was long France's best-selling imported wine. The sandy Doukkala plain is hot and flat, and most of its wine is red and rosé for the domestic and French markets.","rslug":"el-jadida-doukkala"},"ma-gharb":{"name":"Gharb","cat":"AOG","region":"Northern plains (Gharb)","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"The fertile Gharb plain around Sidi Slimane north-east of Kenitra. The fertile alluvial plain behind the Atlantic coast is better known for citrus, rice and sugar beet, and its wines are mostly everyday reds and rosés.","rslug":"northern-plains-gharb"},"ma-guerrouane":{"name":"Guerrouane","cat":"AOG","region":"Meknès and Fès","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"A large AOG west of Meknès known for vin gris and soft reds; Les Celliers de Meknès and Castel source much of their wine here. Clay-limestone soils at around 500 to 600 metres and Atlantic air from the west give softer wines than the hotter east.","rslug":"meknes-and-fes"},"ma-sahel":{"name":"Sahel","cat":"AOG","region":"Rabat and Casablanca","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Coastal zone south of Casablanca. It is one of the five AOGs of the Rabat and Casablanca region, with Atlantic-influenced vineyards. Its exact boundaries could not be verified for this atlas.","rslug":"rabat-and-casablanca"},"ma-saiss":{"name":"Saïss","cat":"AOG","region":"Meknès and Fès","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"The Saïss plain between Meknès and Fès. The plateau lies at around 500 to 600 metres, and its clay-limestone soils supply the large Meknès wineries, mainly with reds and vin gris.","rslug":"meknes-and-fes"},"ma-zaer":{"name":"Zaër","cat":"AOG","region":"Rabat and Casablanca","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"South-east of Rabat around Rommani and Benslimane, home of Thalvin's Domaine des Ouled Thaleb. Sandy soils and Atlantic breezes give the zone fresh rosés and vin gris as well as reds.","rslug":"rabat-and-casablanca"},"ma-zemmour":{"name":"Zemmour","cat":"AOG","region":"Rabat and Casablanca","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Inland from Rabat around Khémisset. The plateau around Khémisset, between Rabat and Meknès, at 300 to 500 metres, makes reds and vin gris for the large Moroccan wineries. It is one of the five Rabat and Casablanca AOGs.","rslug":"rabat-and-casablanca"},"ma-zenata":{"name":"Zenata","cat":"AOG","region":"Rabat and Casablanca","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Coastal hills between Casablanca and Mohammédia, with Atlantic influence. It makes mainly reds and rosés for the Casablanca market, and urban growth has eaten into its vineyards.","rslug":"rabat-and-casablanca"},"ma-zerhoune":{"name":"Zerhoune","cat":"AOG","region":"Meknès and Fès","created":"1970s to 1990s","styles":["red","rose","white"],"grapes":"Cinsault, Carignan, Grenache, Cabernet Sauvignon, Merlot, Syrah","summary":"Hills around Moulay Idriss Zerhoun and the Roman ruins of Volubilis north of Meknès. Vines grew here in Roman times around Volubilis. Today the zone gives reds and rosés from Cinsault, Grenache, Syrah and Cabernet.","rslug":"meknes-and-fes"}}};
